function [m0] = gen_bdot(b, bd, wd, k)
%GEN_BDOT  The generalised B-dot of the Standard Code: m0 = -k (B_dot + w_d x B).
%   b: real[1][3] (passed a plain number)
%   bd: real[1][3] (passed a plain number)
%   wd: real[1][3] (passed a plain number)
%   k: real[1] (passed a plain number)
%   returns m0: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m0 = zeros(3, 1);
    c = [wd(2)*b(3) - wd(3)*b(2); wd(3)*b(1) - wd(1)*b(3); wd(1)*b(2) - wd(2)*b(1)];
    i = ((0):((3) - 1)).';
    m0((i) + 1) = ((-(k)) .* (reshape(bd((i) + 1), [], 1) + reshape(c((i) + 1), [], 1)));
end
